namespace sv_73e92adf98484cc0b31b6f1b546c153c.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<Notification> _notifications = new()
    {
        new(1, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)),
        new(2, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)),
        new(3, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-1)),
    };

    private readonly string[] _fakeMessages =
    [
        "You have a new follower.",
        "Your report is ready to download.",
        "Scheduled maintenance at midnight.",
        "Someone commented on your post.",
        "Your subscription will renew soon.",
        "A new version is available.",
        "Security alert: new login detected.",
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        // Simulate new notifications arriving occasionally
        lock (_notifications)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance each poll
            {
                var msg = _fakeMessages[Random.Shared.Next(_fakeMessages.Length)];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Id > lastId).ToList());
        }
    }
}

